pub fn show(command: Option<&str>) -> Result<(), String> {
    let text=match command{
        None=>"DEVAGATCHI — offline developer pets\n\nUSAGE: devagatchi COMMAND [--global|--repo|--both]\n\nCOMMANDS\n  init NAME [PATH] [MODE]  Adopt a pet; default scope: global, mode: cozy\n  connect                  Connect current repo to global pet; baseline old history\n  status                   Show both applicable pets; no arguments does the same\n  sync [--catch-up]        Feed both applicable pets from new Git line statistics\n  hooks install [--push]  Enable automatic commit feeding (push displays only)\n  hooks status|uninstall  Inspect/remove only unchanged Devagatchi hooks\n  reconcile               Baseline current history without granting food\n  feed LINES               Manually feed positive lines (shares daily food budget)\n  mode cozy|traditional    Change decay rate, preserving elapsed care\n  pet cat|dog|bird|lizard   Change appearance\n  color COLOR              cyan, green, yellow, blue, magenta, red, white, off\n  exclude PATH             Exclude a file/directory prefix from future meals\n  help [COMMAND]           Command-specific help\n\nOPTIONS\n  --global  User-wide pet; --repo  Current checkout pet; --both  Both pets\n  -h, --help  Help; -V, --version  Version\n\nIf both pets exist, choose a scope when feeding or changing settings.\nGlobal state: $XDG_DATA_HOME/devagatchi/pet.txt or ~/.local/share/devagatchi/pet.txt\nRepository state: .devagatchi.local (automatically locally Git-ignored)",
        Some("init")=>"USAGE: devagatchi init NAME [PATH] [cozy|traditional] [--global|--repo]\nDefault: global, current directory, cozy. Existing pets are never overwritten.\nRun twice with different scopes to adopt two pets. Existing commits are the baseline.",
        Some("connect")=>"USAGE: devagatchi connect\nConnect the current checkout to your global pet. Existing history earns no food.",
        Some("status")=>"USAGE: devagatchi status [--global|--repo|--both]\nShows food and mood. Default: both applicable pets. Does not feed or scan history.",
        Some("sync")=>"USAGE: devagatchi sync [--catch-up] [--global|--repo|--both]\nDefault: current repo feeds both applicable pets. Outside a repo: global connections.\n--global scans all connected repos. Up to 200 commits per batch.\n--catch-up processes the oldest unprocessed batch; repeat until complete.\nMeals decay from commit time; old work does not refill your pet today.\nGit reads committed contents locally; the pet gets only statistics and paths.",
        Some("hooks")=>"USAGE: devagatchi hooks install [--push] | status | uninstall\nCommit hooks feed both applicable pets. Installing also connects the global pet.\nExisting hooks and custom core.hooksPath are preserved: automatic installation refuses\nto replace them. In a hook manager, add `devagatchi hook commit` to post-commit and\npost-merge, and `devagatchi hook rewrite \"$@\"` to post-rewrite (preserve its stdin).\nOptional pre-push: `devagatchi hook push`. It shows status BEFORE the push, never feeds.\nHook work is limited to 1 second; missed work is caught by sync. Pet failures never\nreject commits or pushes. No background process is installed.",
        Some("reconcile")=>"USAGE: devagatchi reconcile [--global|--repo|--both]\nBaseline this checkout's current history after an unrecognized rewrite.\nKeeps progress and skips pending history WITHOUT feeding. Use only when intended.",
        Some("feed")=>"USAGE: devagatchi feed LINES [--global|--repo|--both]\nExample: devagatchi feed 25 --both. Manual lines use the same daily formula as commits.",
        Some("mode")=>"USAGE: devagatchi mode cozy|traditional [--global|--repo|--both]\nOld decay applies up to the change. Switching mode does not refill food.",
        Some("pet")=>"USAGE: devagatchi pet cat|dog|bird|lizard [--global|--repo|--both]",
        Some("color")=>"USAGE: devagatchi color cyan|green|yellow|blue|magenta|red|white|off [SCOPE]\nNonempty NO_COLOR, TERM=dumb, and redirected output disable ANSI colors.",
        Some("exclude")=>"USAGE: devagatchi exclude PATH [SCOPE]\nExclude a repository-relative file or directory prefix. No globs. Applies only to future work.",
        Some("help")=>"USAGE: devagatchi help [COMMAND]",
        Some(_)=>return Err("Unknown help command".into()),
    };
    println!("{text}\n\n{}", crate::care::GUIDE);
    Ok(())
}
